function createWeedExplosion() {
    const leafSVG = getPixelLeafSVG();

    for (let i = 0; i < 100; i++) {
        const leaf = document.createElement('div');
        leaf.className = 'weed-leaf';
        leaf.innerHTML = leafSVG;

        const angle = Math.random() * Math.PI * 2;
        const velocity = 20 + Math.random() * 80;
        const tx = Math.cos(angle) * velocity + 'vw';
        const ty = Math.sin(angle) * velocity + 'vh';
        const rot = (Math.random() * 1080 - 540) + 'deg';

        leaf.style.setProperty('--tx', tx);
        leaf.style.setProperty('--ty', ty);
        leaf.style.setProperty('--rot', rot);

        const sizeWidth = 30 + Math.random() * 50;
        leaf.style.width = sizeWidth + 'px';
        leaf.style.height = sizeWidth + 'px';

        leaf.style.animationDuration = (1.5 + Math.random() * 2) + 's';

        document.body.appendChild(leaf);

        setTimeout(() => {
            if (document.body.contains(leaf)) {
                leaf.remove();
            }
        }, 4000);
    }
}

function clearWeedLeaves() {
    document.querySelectorAll('.weed-leaf').forEach(e => e.remove());
}

function recordCurrentLeg() {
    const legPlayers = players.map(p => ({
        profileId: p.profileId || null,
        name: p.name,
        finalScore: p.score,
        won: p.id === winnerPlayerId,
        throwCount: p.history.length,
        throws: [...p.history].reverse().map(h => h.throw),
    }));
    Store.recordLeg({ legNumber, target: TARGET_SCORE, players: legPlayers, matchId: currentMatchId });
    if (winnerPlayerId) {
        legWins[winnerPlayerId] = (legWins[winnerPlayerId] || 0) + 1;
    }
}

function clearScores() {
    players.forEach(p => {
        p.score = 0;
        p.history = [];
    });
}

function nextRound() {
    recordCurrentLeg();
    clearScores();
    legNumber++;
    winnerPlayerId = null;
    winnerModal.classList.add('hidden');
    clearWeedLeaves();
    persistCurrentMatch();
    updateRoundIndicator();
    renderPlayers();
}

function resetMatch() {
    recordCurrentLeg();

    const profileWins = {};
    players.forEach(p => {
        if (!p.profileId) return;
        profileWins[p.profileId] = (profileWins[p.profileId] || 0) + (legWins[p.id] || 0);
    });
    Store.finalizeMatch(profileWins);

    clearScores();
    legWins = {};
    legNumber = 1;
    winnerPlayerId = null;
    currentMatchId = uid();
    winnerModal.classList.add('hidden');
    clearWeedLeaves();
    persistCurrentMatch();
    updateRoundIndicator();
    renderPlayers();
}

function updateRoundIndicator() {
    roundIndicator.textContent = `RONDA ${legNumber}`;
}

function persistCurrentMatch() {
    Store.saveCurrentMatch({
        legNumber,
        legWins,
        matchId: currentMatchId,
        players: players.map(p => ({
            id: p.id,
            name: p.name,
            skin: p.skin.id,
            score: p.score,
            history: p.history,
            profileId: p.profileId,
            locked: p.locked,
            pendingThrow: p.pendingThrow,
        })),
    });
}

